CREATE TABLE password_totp (id UUID PRIMARY KEY DEFAULT uuid_v7(),item_id UUID NOT NULL UNIQUE,vault_id UUID NOT NULL,owner_id UUID NOT NULL,encrypted_secret TEXT NOT NULL,algorithm VARCHAR(16) NOT NULL DEFAULT 'SHA1',digits INTEGER NOT NULL DEFAULT 6,period_seconds INTEGER NOT NULL DEFAULT 30,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,CHECK(algorithm IN ('SHA1','SHA256','SHA512')),CHECK(digits BETWEEN 6 AND 8),CHECK(period_seconds BETWEEN 15 AND 120),FOREIGN KEY(item_id) REFERENCES password_vault_item(id),FOREIGN KEY(vault_id) REFERENCES password_vault(id));
